mapper.select:
SELECT p.product_uid AS product_id , p.product_name AS name , p.product_price AS price , COALESCE(p.product_discount, 0) AS discount , p.category_id AS category_id , p.category_id AS parent_category_id , p.product_created AS product_created FROM product_tb p WHERE p.product_uid IN
#{id}
ORDER BY p.product_uid DESC

SELECT DISTINCT p.product_uid AS product_id , p.product_name AS name , p.product_price AS price , COALESCE(p.product_discount, 0) AS discount , p.category_id AS category_id , p.category_id AS parent_category_id , p.product_created AS product_created FROM product_tb p WHERE 1=1
AND p.product_name ILIKE CONCAT('%', #{searchtxt}, '%')
AND p.product_name ILIKE CONCAT('%', #{kw}, '%')
AND EXISTS ( SELECT 1 FROM product_option_tb po WHERE po.product_uid = p.product_uid AND po.product_color IN
#{c}
)
AND EXISTS ( SELECT 1 FROM product_option_tb po WHERE po.product_uid = p.product_uid AND po.product_size::text IN
#{s}
)
AND 'LFmall' IN
#{b}
ORDER BY p.product_price ASC, p.product_uid DESC
ORDER BY p.product_price DESC, p.product_uid DESC
ORDER BY discount DESC, p.product_uid DESC
ORDER BY p.product_created DESC, p.product_uid DESC
